(() => {
 'use strict';
 const D=window.SITE_DATA, page=document.body.dataset.page, params=new URLSearchParams(location.search);
 let lang=['zh','en'].includes(params.get('lang'))?params.get('lang'):'en';
 if(!['en','zh'].includes(lang))lang='en';
 const UI={
 en:{home:'Home',research:'Research',publications:'Publications',portfolio:'Portfolio',education:'Education',teaching:'Academic Service',personal:'Beyond Research',contact:'Contact',about:'About Me',selected:'Selected Publications',manuscripts:'Research Manuscripts',interests:'RESEARCH INTERESTS',service:'Academic Service',honors:'Selected Recognition',grants:'Research Projects',engineering:'Research Engineering',more:'Explore the complete research portfolio →',overview:'Research Portfolio',portfolioTitle:'From visual evidence to clinical understanding.',thread:'Reliability → Generalization → Clinical Validation',all:'All work',reliability:'Reliable generation',generalization:'Generalization',foundation:'Foundation models',clinical:'Clinical AI',details:'Methods, contribution & evidence',question:'Research question',method:'Method',contribution:'My contribution',evidence:'Evidence & evaluation',figures:'Original figures',demos:'Systems & Demonstrations',talks:'Talks & Presentations',certificate:'Reviewer certificate',certificateTitle:'IEEE SMC 2026 · Reviewer',certificateBody:'Certificate of Appreciation for reviewing at IEEE SMC 2026, held October 4–7, 2026 in Bellevue, WA, USA.',outlook:'Future Research',updated:'Updated October 2026',top:'Back to top ↑',zoom:'Enlarge image',close:'Close',poster:'Watch the recorded demonstration using the player controls.',recording:'SS-ACL · ACM Multimedia 2025 presentation',recordingNote:'Recorded research presentation accompanying SS-ACL.',cache:'View cached demonstration recording',cachedMode:'Cached demonstration recording',virtual:'Virtual case screenshot',skip:'Skip to content',figNote:'Original research figures retain the language used in the source manuscripts.',readnote:'Read the note',journal:'Personal Notes'},
 zh:{home:'首页',research:'研究方向',publications:'学术论文',portfolio:'作品集',education:'教育经历',teaching:'学术服务',personal:'研究之外',contact:'联系',about:'关于我',selected:'代表论文',manuscripts:'在研与投稿工作',interests:'研究兴趣',service:'学术服务',honors:'代表性荣誉',grants:'科研项目',engineering:'科研与工程能力',more:'查看完整研究作品集 →',overview:'研究作品集',portfolioTitle:'从视觉证据，到临床理解。',thread:'报告可靠性 → 模型泛化性 → 临床适用性',all:'全部工作',reliability:'可靠生成',generalization:'泛化能力',foundation:'基础模型',clinical:'临床智能',details:'展开方法、贡献与实验依据',question:'研究问题',method:'方法思路',contribution:'个人贡献',evidence:'实验与验证',figures:'原始图表',demos:'系统与演示',talks:'学术报告与展示',certificate:'审稿证书',certificateTitle:'IEEE SMC 2026 · 审稿人',certificateBody:'IEEE SMC 2026 审稿感谢证书。会议于 2026 年 10 月 4—7 日在美国华盛顿州贝尔维尤举行。',outlook:'未来研究',updated:'更新于 2026 年 10 月',top:'返回顶部 ↑',zoom:'放大图片',close:'关闭',poster:'使用播放器观看演示。',recording:'SS-ACL · ACM MM 2025 研究展示',recordingNote:'SS-ACL 论文配套的研究展示录屏。',cache:'查看缓存演示录屏',cachedMode:'缓存模式演示录屏',virtual:'虚拟病例界面截图',skip:'跳转到正文',figNote:'原始论文图表保留源稿件中的语言。',readnote:'读这篇小记',journal:'生活小记'}};
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const t=v=>typeof v==='object'&&!Array.isArray(v)?v[lang]:v;
 const im=n=>'assets/images/'+n, vid=n=>'assets/videos/'+n;
 const link=(label,url)=>`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`;
 const figure=(file,caption,cls='')=>`<figure class="figure ${cls}"><button class="image-button" data-zoom="${e(im(file))}" data-caption="${e(caption)}" aria-label="${e(UI[lang].zoom)}: ${e(caption)}"><img loading="lazy" src="${e(im(file))}" alt="${e(caption)}"></button><figcaption>${e(caption)}</figcaption></figure>`;
 const imageButton=(file,alt,cls='')=>`<button class="image-button ${cls}" data-zoom="${e(im(file))}" data-caption="${e(alt)}" aria-label="${e(UI[lang].zoom)}: ${e(alt)}"><img class="${cls}" loading="lazy" src="${e(im(file))}" alt="${e(alt)}"></button>`;
 function paper(p){const u=UI[lang];return `<article class="pub ${['sfm','gmvlp','snot'].includes(p.id)?'manuscript':''}"><a class="pub-title" href="portfolio.html?lang=${lang}#${p.id}">${e(t(p.title))}</a>${p.authors?`<div class="authors">${e(p.authors)}</div>`:''}<div class="venue">${e(t(p.status))}<span class="badge">${e(t(p.role))}</span></div><div class="pub-actions">${p.links.map(l=>link(t(l.label),l.url)).join('')}<a href="portfolio.html?lang=${lang}#${p.id}">${e(u.research)} →</a></div></article>`}
 function sidebar(){const u=UI[lang],home=`index.html?lang=${lang}`,port=`portfolio.html?lang=${lang}`;return `<aside class="sidebar"><div class="language" aria-label="Language"><button data-lang="en" aria-pressed="${lang==='en'}">English</button><button data-lang="zh" aria-pressed="${lang==='zh'}">中文</button></div><button class="portrait-link" data-zoom="${im('portrait-conference.jpg')}" data-caption="${e(t(D.name))}" aria-label="${e(u.zoom)}"><img class="portrait" src="${im('portrait-conference.jpg')}" alt="${e(t(D.name))}"></button><a class="wordmark" href="${home}">${e(t(D.name))}</a><div class="affiliation">${lang==='en'?'Medical Vision-Language Learning<br>Tongji University':'医学视觉语言学习<br>同济大学'}</div><nav class="navigation" aria-label="${e(u.home)}"><a class="${page==='home'?'active':''}" href="${home}">${u.home}</a><a href="${home}#research">${u.research}</a><a href="${home}#publications">${u.publications}</a><a class="${page==='portfolio'?'active':''}" href="${port}">${u.portfolio}</a>${page==='portfolio'?`<a href="#demonstrations">${u.demos}</a><a href="#presentations">${u.talks}</a>`:''}<a href="${home}#education">${u.education}</a><a href="${home}#service">${u.teaching}</a><a href="${home}#personal">${u.personal}</a>${page==='journal'?`<a class="active" href="journal.html?lang=${lang}">${u.journal}</a>`:''}</nav><div class="contact"><a href="mailto:${D.email}">${D.email}</a>${link('Google Scholar',D.scholar)}${link('GitHub',D.github)}</div><div class="sidefoot">${u.updated}<br>© 2026 ${e(t(D.name))}</div></aside>`}
 function home(){const u=UI[lang],selected=['ssacl','vat','midol','radlas','xmid'].map(id=>D.research.find(p=>p.id===id));return `<div class="eyebrow">${lang==='en'?'Medical AI · Multimodal Learning':'医学人工智能 · 多模态学习'}</div><h1>${u.about}</h1>${t(D.bio).map((p,i)=>`<p class="${i===0?'intro':'body-copy'}">${e(p)}</p>`).join('')}<div class="quicklinks">${link('Google Scholar',D.scholar)}${link('GitHub',D.github)}<a href="portfolio.html?lang=${lang}">${u.portfolio} →</a></div><div class="interests" id="research"><strong>${u.interests}</strong>${t(D.interests).map(x=>`<span>${e(x)}</span>`).join('')}</div><h2 id="publications">${u.selected}</h2>${selected.map(paper).join('')}<h2>${u.manuscripts}</h2>${['sfm','gmvlp','snot'].map(id=>paper(D.research.find(x=>x.id===id))).join('')}<p><a class="back-top" href="portfolio.html?lang=${lang}">${u.more}</a></p><h2 id="education">${u.education}</h2>${D.education.map(x=>`<div class="table-row"><div><strong>${e(t(x.name))}</strong> · ${e(t(x.degree))}<small>${e(t(x.detail))}</small></div><span class="date">${e(x.date)}</span></div>`).join('')}<h2>${u.engineering}</h2><div class="skills">${D.skills.map(x=>`<div><strong>${e(t(x)[0])}</strong>${e(t(x)[1])}</div>`).join('')}</div><h2>${u.grants}</h2>${D.projects_grants.map(x=>`<div class="grant"><strong>${e(t(x)[0])}</strong>${e(t(x)[1])}</div>`).join('')}<h2 id="service">${u.service}</h2><div class="service-layout"><div><p class="body-copy">${e(t(D.service))}</p></div>${imageButton('reviewer-smc2026.png',u.certificate,'certificate-button')}</div><h2>${u.honors}</h2><ul class="honors"><li>${lang==='en'?'ACM MM 2025 Best Paper Candidate — SS-ACL, first author.':'ACM MM 2025 最佳论文候选：SS-ACL，第一作者。'}</li><li>${lang==='en'?'ACM MM 2025 Outstanding Paper Award — RadLAS, corresponding author.':'ACM MM 2025 杰出论文奖：RadLAS，通讯作者。'}</li><li>${lang==='en'?'First Prize, Jiangxi Graduate Mathematical Modeling Competition (2020).':'2020 年江西省研究生数学建模竞赛一等奖。'}</li></ul><h2 id="personal">${u.personal}</h2><div class="personal"><p class="body-copy">${e(t(D.personal))}</p>${imageButton('personal-swimming.jpg',lang==='en'?'Swimming and exercise':'游泳与运动','personal-photo')}</div><article class="journal-preview">${imageButton(D.journal.photo,t(D.journal.caption),'badminton-preview')}<div><h3>${e(t(D.journal.title))}</h3><p class="body-copy">${e(t(D.journal.excerpt))}</p><a class="back-top" href="journal.html?lang=${lang}">${u.readnote} →</a></div></article><h2>${u.outlook}</h2><p class="body-copy">${e(t(D.outlook))}</p><h2 id="contact">${u.contact}</h2><p class="body-copy">${link(D.email,'mailto:'+D.email)}</p>`}
 function journal(){const u=UI[lang],j=D.journal;return `<article class="journal-entry"><div class="eyebrow">${u.personal}</div><h1>${e(t(j.title))}</h1><p class="journal-subtitle">${e(t(j.subtitle))}</p>${figure(j.photo,t(j.caption))}<div class="journal-prose">${t(j.paragraphs).map(p=>`<p>${e(p)}</p>`).join('')}</div><p class="journal-back"><a href="index.html?lang=${lang}#personal">← ${u.personal}</a></p></article>`}
 function project(p){const u=UI[lang],cover=p.figures[0];return `<article class="project" id="${p.id}" data-category="${p.category}"><div class="project-overview">${cover?`<button class="image-button" data-zoom="${e(im(cover.file))}" data-caption="${e(t(cover.caption))}" aria-label="${e(u.zoom)}"><img class="project-cover" loading="lazy" src="${im(cover.file)}" alt="${e(t(cover.caption))}"></button>`:`<div class="midol-diagram"><span>${lang==='en'?'5 imaging<br>modalities':'5 类<br>影像模态'}</span><b>→</b><span>${lang==='en'?'Information<br>decomposition':'信息分解'}</span><b>→</b><span>${lang==='en'?'21 clinical<br>tasks':'21 项<br>临床任务'}</span></div>`}<div><div class="status">${e(t(p.status))}</div><h3>${e(t(p.name))}</h3><div class="meta">${e(t(p.role))}</div><p class="summary">${e(t(p.summary))}</p><div class="pub-actions">${p.links.map(l=>link(t(l.label),l.url)).join(' &nbsp; ')}</div></div></div><details class="details"><summary>${u.details}</summary><div class="project-copy">${[['question','problem'],['method','method'],['contribution','contribution'],['evidence','evidence']].map(([label,k])=>`<div><h4>${u[label]}</h4><p>${e(t(p[k]))}</p></div>`).join('')}</div>${p.figures.map(f=>figure(f.file,t(f.caption))).join('')}${p.id==='snot'?`<a href="#snot-demo">${u.demos} ↓</a>`:''}</details></article>`}
 function demo(d){const u=UI[lang];return `<article class="demo" id="${d.id}"><span class="mode">${e(t(d.mode))}</span><h3>${e(t(d.name))}</h3><p>${e(t(d.summary))}</p>${d.video?`<video controls controlslist="nodownload" playsinline preload="metadata" poster="${im(d.cover)}" aria-label="${e(t(d.name))}"><source src="${vid(d.video)}" type="video/mp4"><a href="${vid(d.video)}">${e(t(d.name))}</a></video><div class="video-note">${u.poster}</div>`:imageButton(d.cover,t(d.name),'demo-cover')}<p>${e(t(d.detail))}</p>${d.gallery.length?`<div class="gallery">${d.gallery.map(f=>imageButton(f,t(d.name))).join('')}</div>`:''}${d.id==='visionscope'?`<details class="details"><summary>${u.cache}</summary><p class="caption">${u.cachedMode}</p><video controls controlslist="nodownload" playsinline preload="none" poster="${im('visionscope-01-home.png')}"><source src="${vid('visionscope-cached-demo.mp4')}" type="video/mp4"></video></details>`:''}</article>`}
 function portfolio(){const u=UI[lang];return `<div class="eyebrow">${lang==='en'?'Selected Work · 2021–2026':'研究与系统 · 2021—2026'}</div><h1>${u.portfolioTitle}</h1><p class="body-copy">${e(t(D.tagline))}</p><div class="research-thread"><b>${u.thread}</b><br>VaT / SS-ACL → GM-VLP / SNOT → SFM</div><div class="downloads"><a href="#demonstrations">${u.demos} ↓</a><a href="#presentations">${u.talks} ↓</a></div><div class="filters" role="group" aria-label="${u.research}">${['all','reliability','generalization','foundation','clinical'].map((k,i)=>`<button data-filter="${k}" aria-pressed="${!i}">${u[k]}</button>`).join('')}</div><section id="projects">${D.research.map(project).join('')}</section><section class="demo-section" id="demonstrations"><h2>${u.demos}</h2>${D.demos.map(demo).join('')}</section><section id="presentations"><h2>${u.talks}</h2><h3>${u.recording}</h3><video class="talk-video" controls controlslist="nodownload" playsinline preload="metadata" poster="${im('ssacl-talk-poster.jpg')}"><source src="${vid('ssacl-presentation.mp4')}" type="video/mp4"></video><p class="caption">${u.recordingNote}</p>${D.liveTalk?`<h3>${e(t(D.liveTalk.title))}</h3><video class="talk-video" controls controlslist="nodownload" playsinline preload="metadata" poster="${im(D.liveTalk.poster)}"><source src="${vid(D.liveTalk.file)}" type="video/mp4"></video>`:''}</section><section id="certificates"><h2>${u.service}</h2><p class="body-copy">${e(t(D.service))}</p><h3>${u.certificateTitle}</h3><p class="body-copy">${u.certificateBody}</p>${figure('reviewer-smc2026.png',u.certificateTitle)}</section>`}
 function bind(){document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{const chosen=b.dataset.lang;if(chosen===lang)return;const scroll=window.scrollY;lang=chosen;try{localStorage.setItem('ly-language',lang)}catch{}const url=new URL(location);url.searchParams.set('lang',lang);history.replaceState(null,'',url);render();window.scrollTo(0,scroll)}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));document.querySelectorAll('.project').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter)}));const box=document.querySelector('#lightbox');document.querySelectorAll('[data-zoom]').forEach(b=>b.addEventListener('click',()=>{box.querySelector('img').src=b.dataset.zoom;box.querySelector('img').alt=b.dataset.caption||'';box.querySelector('p').textContent=b.dataset.caption||'';box.showModal()}));box.querySelector('button').onclick=()=>box.close();box.onclick=ev=>{if(ev.target===box)box.close()};document.querySelectorAll('video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('video').forEach(other=>{if(other!==v)other.pause()})));}
 function revealHash(){const target=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(target?.matches('.project')){const details=target.querySelector('details');if(details)details.open=true}if(target)requestAnimationFrame(()=>target.scrollIntoView());}
 function render(){const u=UI[lang];document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.body.className=lang;document.title=(page==='home'?t(D.name):(page==='journal'?t(D.journal.title):u.overview)+' | '+t(D.name))+' · '+(lang==='en'?'Medical AI':'医学人工智能');document.querySelector('.skip').textContent=u.skip;document.querySelector('#lightbox button').setAttribute('aria-label',u.close);document.querySelector('#app').innerHTML=`<div class="layout">${sidebar()}<main class="main" id="main">${page==='home'?home():page==='journal'?journal():portfolio()}<footer class="footer">© 2026 ${e(t(D.name))} · ${u.updated}<br><a href="mailto:${D.email}">${D.email}</a> &nbsp; / &nbsp; <a href="#main">${u.top}</a></footer></main></div>`;bind();}
 render();revealHash();window.addEventListener('hashchange',revealHash);
})();
